import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.LongAdder;

/**
 * Simulation of Asia Pacific Airport operations.
 * Implements capacity limits and concurrent servicing requirements.
 */
public class AirportSystem {
    private final Semaphore runway = new Semaphore(1, true);
    private final Semaphore groundCapacity = new Semaphore(3, true);
    private final Semaphore gates = new Semaphore(3, true);
    private final Semaphore fuelTruck = new Semaphore(1, true);

    private final AtomicInteger planesServed = new AtomicInteger(0);
    private final LongAdder totalWaitTime = new LongAdder();

    class Airplane implements Runnable {
        private final int id;
        private final boolean isEmergency;

        Airplane(int id, boolean isEmergency) {
            this.id = id;
            this.isEmergency = isEmergency;
        }

        @Override
        public void run() {
            long arrivalTime = System.currentTimeMillis();
            try {
                System.out.println("Plane " + id + (isEmergency ? " [EMERGENCY]" : "") + " requesting landing.");

                // Acquire ground spot and runway
                groundCapacity.acquire();
                runway.acquire();

                System.out.println("Plane " + id + " landing on runway.");
                Thread.sleep(500); // Landing time
                runway.release();

                gates.acquire();
                System.out.println("Plane " + id + " docked at gate. (Ground occupancy: " + (3 - groundCapacity.availablePermits()) + ")");

                // Concurrent servicing
                CountDownLatch latch = new CountDownLatch(3);

                new Thread(() -> { performTask("Disembarking/Embarking", 1000); latch.countDown(); }).start();
                new Thread(() -> { performTask("Cleaning", 800); latch.countDown(); }).start();
                new Thread(() -> {
                    try {
                        fuelTruck.acquire();
                        performTask("Refuelling", 1200);
                        fuelTruck.release();
                        latch.countDown();
                    } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                }).start();

                latch.await();

                // Takeoff
                runway.acquire();
                System.out.println("Plane " + id + " taking off.");
                Thread.sleep(500);

                gates.release();
                runway.release();
                groundCapacity.release();

                planesServed.incrementAndGet();
                totalWaitTime.add(System.currentTimeMillis() - arrivalTime);
                System.out.println("Plane " + id + " departed safely.");

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        private void performTask(String name, int ms) {
            try { Thread.sleep(ms); } catch (InterruptedException e) { }
        }
    }

    public void startSimulation() {
        ExecutorService service = Executors.newCachedThreadPool();

        // Scenario setup
        service.execute(new Airplane(1, false)); // Occupies Gate 1
        service.execute(new Airplane(2, false)); // Occupies Gate 2
        try { Thread.sleep(100); } catch (Exception e) {}
        service.execute(new Airplane(3, false)); // Fills Ground Cap (3/3)
        service.execute(new Airplane(4, false)); // Must wait outside
        service.execute(new Airplane(99, true)); // Emergency landing request

        service.shutdown();
        try {
            service.awaitTermination(30, TimeUnit.SECONDS);
            System.out.println("\n--- STATISTICS ---");
            System.out.println("Planes Served: " + planesServed.get());
            System.out.println("Avg Turnaround: " + (totalWaitTime.sum() / Math.max(1, planesServed.get())) + "ms");
        } catch (InterruptedException e) { }
    }

    public static void main(String[] args) {
        new AirportSystem().startSimulation();
        System.out.println("[REQUIRES STUDENT'S OWN EVIDENCE: 5-minute video demonstration of the code execution]");
    }
}
